recipes.code:
{
  "inputs": [
    {
      "id": "blixtworks-private-key",
      "type": "promptString",
      "description": "Private key of a wallet holding a small amount of USDC on Base. Used only to sign per-request payments (well under a cent per call). Use a dedicated low-balance wallet. Without it the free status tool still works.",
      "password": true
    }
  ],
  "servers": {
    "tools": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "blixtworks-mcp@1.1.0"
      ],
      "env": {
        "BLIXTWORKS_PRIVATE_KEY": "${input:blixtworks-private-key}"
      }
    }
  }
}
